def build_agent(sandbox):
    # Main beam (chassis) with sufficient buoyancy
    main_beam = sandbox.add_beam(x=5.0, y=1.5, width=2.0, height=0.8, density=100.0)

    # Paddles for propulsion and buoyancy control
    left_paddle = sandbox.add_beam(x=4.5, y=1.5, width=0.5, height=0.5, density=100.0)
    right_paddle = sandbox.add_beam(x=5.5, y=1.5, width=0.5, height=0.5, density=100.0)
    front_paddle = sandbox.add_beam(x=5.0, y=1.65, width=0.5, height=0.5, density=100.0)
    back_paddle = sandbox.add_beam(x=5.0, y=1.35, width=0.5, height=0.5, density=100.0)

    # Connect paddles to main beam (rigid joints)
    sandbox.add_joint(main_beam, left_paddle, anchor_point=(4.5, 1.5), type='rigid')
    sandbox.add_joint(main_beam, right_paddle, anchor_point=(5.5, 1.5), type='rigid')
    sandbox.add_joint(main_beam, front_paddle, anchor_point=(5.0, 1.65), type='rigid')
    sandbox.add_joint(main_beam, back_paddle, anchor_point=(5.0, 1.35), type='rigid')

    return [main_beam, left_paddle, right_paddle, front_paddle, back_paddle]

def agent_action(sandbox, agent_body, step_count):
    # Apply force to paddles every 200 steps
    if step_count % 200 == 0:
        for body in sandbox.bodies:
            # Left paddle
            if abs(body.position.x - 4.5) < 0.1 and abs(body.position.y - 1.5) < 0.1:
                sandbox.apply_force(body, -520, 0, step_count)
            # Right paddle
            elif abs(body.position.x - 5.5) < 0.1 and abs(body.position.y - 1.5) < 0.1:
                sandbox.apply_force(body, -520, 0, step_count)
            # Front paddle
            elif abs(body.position.x - 5.0) < 0.1 and abs(body.position.y - 1.65) < 0.1:
                sandbox.apply_force(body, 0, 520, step_count)
            # Back paddle
            elif abs(body.position.x - 5.0) < 0.1 and abs(body.position.y - 1.35) < 0.1:
                sandbox.apply_force(body, 0, -520, step_count)
        # Check if in deep channel
        current_front_x = sandbox.get_vehicle_front_x()
        if 16.5 <= current_front_x <= 19.5:
            for body in sandbox.bodies:
                if abs(body.position.x - 5.0) < 0.1 and abs(body.position.y - 1.65) < 0.1:
                    sandbox.apply_force(body, 0, 520, step_count)
